templates.camera_carlo:
{% set now_s = as_timestamp(now()) %}
{% set temperature = states('sensor.temperatura_camera_carlo') | float(none) %}
{% set target = state_attr('climate.trv_vtherm_camera_carlo', 'temperature') | float(none) %}
{% set power = states('sensor.energy_meter_power_a_casa') | float(none) %}
{% set power_limit = 1100 %}
{% set hold_seconds = 120 %}
{% set temp_age = now_s - as_timestamp(states['sensor.temperatura_camera_carlo'].last_reported, 0) %}
{% set power_age = now_s - as_timestamp(states['sensor.energy_meter_power_a_casa'].last_reported, 0) %}
{% set cycle = states('input_text.camera_carlo_pdc_ciclo') | from_json({}) %}
{% set cycle = cycle if cycle is mapping else {} %}
{% set stopped = cycle.get('off') | float(none) %}
{% set own_recent = cycle.get('m') != 'off' or stopped is none or stopped > now_s - 600 or stopped < 0 %}
{% set schedule_stop = states('sensor.camera_carlo_pdc_prossimo_stop_programma') %}
{% set schedule_stop_ts = schedule_stop | float(none) %}
{% set checks = [
  ('schedule_change', schedule_stop_ts is not none and schedule_stop_ts <= now_s + 600),
  ('data_missing', schedule_stop != 'none' and schedule_stop_ts is none),
  ('manual_override', is_state('input_boolean.camera_carlo_pdc_override','on')),
  ('window', is_state('binary_sensor.finestra_interna_camera_carlo', 'on')),
  ('data_missing', not is_state('binary_sensor.finestra_interna_camera_carlo', 'off') or not has_value('climate.trv_vtherm_camera_carlo') or not has_value('climate.camera_carlo_condizionatore') or not has_value('climate.camera_carlo_pompa_di_calore') or not has_value('input_boolean.camera_carlo_pdc_in_gestione')),
  ('managed', is_state('input_boolean.camera_carlo_pdc_in_gestione', 'on')),
  ('automatic_off', is_state('input_boolean.camera_carlo_pdc_automatica', 'off')),
  ('data_missing', not is_state('input_boolean.camera_carlo_pdc_automatica', 'on') or not is_state('input_boolean.camera_carlo_pdc_in_gestione', 'off') or not has_value('select.central_mode')),
  ('central_mode', states('select.central_mode') not in ['Auto', 'Heat only']),
  ('room_off', ((state_attr('climate.trv_vtherm_camera_carlo', 'requested_state') or {}).get('hvac_mode')) != 'heat' or not is_state('climate.trv_vtherm_camera_carlo', 'heat')),
  ('preset', not (state_attr('climate.trv_vtherm_camera_carlo', 'preset_mode') in ['none', 'eco', 'comfort', 'boost'] or is_state('timer.override_riscaldamento_camera_carlo', 'active') or (is_state('timer.override_riscaldamento_camera_carlo', 'idle') and is_state('switch.schedule_camera_carlo_vtherm_feriale', 'off') and is_state('switch.schedule_camera_carlo_vtherm_weekend', 'off')))),
  ('temperature_missing', temperature is none or target is none or temp_age > 3600),
  ('at_target', temperature is not none and target is not none and temperature >= target),
  ('small_gap', temperature is not none and target is not none and target - temperature < 0.4 - 0.000001),
  ('power_missing', power is none or power_age > 45 or (power is not none and power < 0)),
  ('power_high', power is not none and power > power_limit),
  ('other_pdc', is_state('input_boolean.camera_diego_luisa_pdc_in_gestione', 'on') or (has_value('climate.camera_diego_luisa_condizionatore_aria_stanza') and not is_state('climate.camera_diego_luisa_condizionatore_aria_stanza', 'off'))),
  ('data_missing', not has_value('input_boolean.camera_diego_luisa_pdc_in_gestione') or not has_value('climate.camera_diego_luisa_condizionatore_aria_stanza')),
  ('split_busy', not is_state('climate.camera_carlo_condizionatore', 'off') or not is_state('climate.camera_carlo_pompa_di_calore', 'off')),
  ('data_missing', not has_value('input_text.camera_carlo_pdc_ciclo') or stopped is none),
  ('cooldown', own_recent)
] %}
{% set reasons = checks | selectattr('1') | map(attribute='0') | unique | list %}
{{ (reasons | join(',') if reasons else 'ready') ~ '|' ~ power_limit ~ '|' ~ hold_seconds }}

